INSERT INTO Estatus (IdEstatus, NombreEstatus) VALUES
  (1, 'Pendiente'),
  (2, 'En proceso'),
  (3, 'Entregado');
INSERT INTO Acreditacion (IdAcreditacion, NombreAcreditacion) VALUES
  (1, 'Pendiente'),
  (2, 'En revisión'),
  (3, 'Aceptado'),
  (4, 'Publicado');
INSERT INTO Categoria (IdCategoria, ClaveCategoria, NombreCategoria, DefinicionCategoria) VALUES
  (1, 'I.1.1', 'Productividad Docente', 'Actividades que impacten favorablemente el proceso enseñanza-aprendizaje en sus distintas modalidades: presencial, presencial dual, en línea y mixta.'),
  (2, 'I.2', 'Investigación', 'Procedimiento reflexivo que comprende un método sistemático, controlado y crítico que permite describir nuevos hechos o datos para indagar sobre hechos o circunstancias con el fin de desarrollar o contribuir a un conocimiento generalizable en cualquier campo del conocimiento, produciendo resultados para llegar a conclusiones.'),
  (3, 'I.3', 'Tutoría a estudiantes', NULL),
  (4, 'I.4', 'Cuerpos Colegiados y Gestión Académica', NULL),
  (5, 'O.1', 'Otras evidencias', NULL);
INSERT INTO TipoEvidencia (IdTipoEvidencia, ClaveTipoEvidencia, NombreTipoEvidencia, DefinicionTipoEvidencia, ContenidoAcreditacion, PuntajeMaximo, IdCategoria) VALUES
  (1, 'I.1.1.1', 'Diseño de Planes de Estudio en sus diversos grados y modalidades.', 'Elaboración de un nuevo plan de estudios para ofertar como propuesta formativa. Los componentes de un plan de estudios se elaboran de acuerdo con los criterios técnicos establecidos conforme a la normatividad institucional vigente para la implementación de nuevos Planes de Estudio. Dentro de las actividades específicas se considera, el diseño de los espacios educativos correspondientes.', '1) La Secretaría General Administrativa acredita mediante el acta de aprobación del plan de estudios emitida por el Colegio Universitario. 2) El Colegio Departamental acreditará, la participación en actividades específicas, mediante la constancia avalada y aprobada por la persona que coordina a la comisión responsable de la elaboración del plan de estudios.', 180, 1),
  (2, 'I.1.1.2', 'Reestructuración de planes de estudio en los diversos grados y modalidades.', 'Diseño de las modificaciones a la estructura de un plan de estudios, cuando este tiene cinco años o más de vigencia desde su última aprobación, cuando los cambios que se proponen exceden el 30% del valor total de los créditos obligatorios del área básica y vocacional.', '1) La Secretaría General Administrativa acredita mediante el acta de aprobación del plan de estudios emitida por el Colegio Universitario. 2) El Colegio Departamental acreditará, la participación en actividades específicas, mediante constancia avalada y aprobada por la persona que coordina a la comisión responsable de la elaboración del plan de estudios.', 180, 1),
  (3, 'I.1.1.3', 'Adecuación de Planes de Estudio.', 'Elaboración de la propuesta de adecuación a un plan de estudio vigente lo que comprende: cambio de nombre y seriación de asignaturas, la unión, separación, supresión, adición o actualización de las mismas y los cambios de periodo escolar. Las adecuaciones pueden realizarse en los espacios educativos obligatorios de las áreas de formación básica y formación vocacional. La adecuación no excede del 30% del valor total de créditos de las dos áreas.', '1) El Colegio Departamental acredita mediante constancia del acuerdo de aprobación de la adecuación. 2) El Colegio Departamental acreditará la participación en actividades específicas, mediante constancia avalada y aprobada por la persona que coordina a la comisión responsable de la adecuación del plan de estudios.', 60, 1),
  (4, 'I.1.1.4', 'Diseño de programa de diplomados, cursos o talleres.', 'Elaboración del proyecto formativo en términos de la normatividad vigente, considerando la definición del tipo didáctico.', 'El Colegio de la Facultad acredita mediante el acta de aprobación del informe de los diplomados, cursos o talleres impartidos. La Secretaría General Académica o las Direcciones Administrativas acreditan los diplomados, cursos o talleres, mediante oficio de aprobación del informe del proyecto formativo aprobado por dicha Secretaría.', 60, 1),
  (5, 'I.1.1.5', 'Elaboración de material didáctico con tecnologías educativas.', 'Proceso que comprende el diseño, la validación y la producción de recursos educativos digitales, impresos o electrónicos, elaborados para el aprendizaje, la enseñanza o la evaluación, cuyo acceso se encuentre siempre disponible de manera libre para ser utilizado por personal académico y estudiantes a través de páginas institucionales.', 'El Colegio Departamental acredita con el acta correspondiente, a solicitud de la academia respectiva, la pertinencia del material para el plan de estudios correspondiente. El material didáctico debe emplear recursos audiovisuales, instrumentales y/o multimedia.', 45, 1),
  (6, 'I.1.1.6', 'Elaboración de Manuales de prácticas.', 'Elaboración de textos editados metódica y sistemáticamente para ser utilizados como guía de actividades, prácticas de laboratorio, de campo y de talleres.', '(se acredita un solo manual por espacio educativo): El Colegio Departamental acredita con el acta correspondiente, a solicitud de la academia respectiva, la pertinencia del material y su uso generalizado en el plan de estudios correspondiente. Para ello, el Colegio Departamental deberá revisar la portada, página legal que incluya ISBN y colofón en caso de manuales de prácticas impresos.', 45, 1),
  (7, 'I.1.1.7', 'Proyectos de docencia.', 'Son aquellos proyectos cuyos objetivos están enfocados en mejorar la calidad y/o apoyar el proceso de enseñanza-aprendizaje; pudiendo ser de carácter temporal o continuo. Los proyectos aprobados por los Colegios Departamentales o por los Colegios de Facultades Interdisciplinarias deberán incidir en la mejora de al menos uno de los indicadores aprobados en los planes de desarrollo del programa(s) educativo(s), Departamento, o Facultad Interdisciplinaria correspondiente. Por lo anterior, los proyectos registrados deberán establecer las metas para cada indicador que se pretende mejorar.', '1.1) Registro del proyecto en plataforma electrónica institucional desarrollada para tal fin. 2.2) Captura del informe de actividades en plataforma electrónica, el cual deberá ser aprobado por el Colegio de la Facultad interdisciplinaria si es interdisciplinario, o por el Colegio Departamental, si es disciplinario. 2.3) Cumplimiento de al menos el 80% de las metas anuales establecidas en el proyecto.', 40, 1),
  (8, 'I.1.1.8', 'Autoría de libro.', 'Autoría de libro del área de conocimiento donde se desempeña el personal académico (en apoyo a la docencia, a la investigación o la difusión de la ciencia o arte), aprobado por el Comité editorial de la Facultad Interdisciplinaria o por un Comité editorial de una colección. La obra debe publicarse en una editorial institucional - entendida como cualquier editorial perteneciente a una institución de educación superior, centro de investigación u organismo académico -, en coedición o en una editorial reconocida por su prestigio académico, excluyendo aquellas que no cuenten con procesos de dictamen académico o que sean de carácter comercial sin arbitraje.', 'El Colegio de Facultad Interdisciplinaria acredita, a solicitud de la academia respectiva, la congruencia disciplinar del libro en el área del conocimiento del docente, previamente dictaminado a doble ciego por pares académicos o aprobado por un comité editorial. Para ello, el Colegio de la Facultad Interdisciplinaria deberá revisar la portada, página legal que incluya ISBN y colofón en caso de libros impresos.', 180, 1),
  (9, 'I.1.1.9', 'Autoría de capítulo de libro', 'Autoría de capítulo de libro del área de conocimiento donde se desempeña el académico (en apoyo a la docencia, a la investigación o la difusión de la ciencia o arte). aprobado por el Comité editorial de la Facultad Interdisciplinaria o por un Comité editorial de una colección. La obra debe publicarse en una editorial institucional - entendida como cualquier editorial perteneciente a una institución de educación superior, centro de investigación u organismo académico -, en coedición o en una editorial reconocida por su prestigio académico, excluyendo aquellas que no cuenten con procesos de dictamen académico o que sean de carácter comercial sin arbitraje.', '(se acredita un solo capítulo por libro): El Colegio Departamental evalúa a solicitud de la academia respectiva, la congruencia disciplinar del libro en el área de conocimiento del docente, previamente dictaminado a doble ciego por pares académicos o aprobado por un comité editorial, para turnarlo al Colegio de la Facultad Interdisciplinaria para la revisión y acreditación de la actividad. Para ello, el Colegio de la Facultad Interdisciplinaria deberá revisar la portada, página legal que incluya ISBN y colofón en caso de libros impresos.', 80, 1),
  (10, 'I.1.1.10', 'Traducción de libro.', 'Traducción al español o a una lengua diferente, de libro del área de conocimiento donde se desempeña el académico (en apoyo a la docencia, a la investigación o la difusión de la ciencia o arte), publicado por una editorial y que cuenta con registro ISBN.', 'El Colegio Departamental evalúa, a solicitud de la academia respectiva, la congruencia disciplinar del libro en el área de conocimiento del docente para turnarlo al Colegio de la Facultad Interdisciplinaria para la revisión y acreditación de la actividad. Para ello, el Colegio de la Facultad Interdisciplinaria deberá revisar la portada, página legal que incluya ISBN y colofón en caso de libros impresos. En aquellos casos que en las evidencias presentadas no aparezca el nombre del traductor, deberá entregar, además, el documento escrito emitido por la editorial, donde conste su participación como traductor del libro.', 80, 1),
  (11, 'I.1.1.11', 'Traducciones de capítulos de libro.', 'Traducción al español o a una lengua diferente, de capítulo de libro del área de conocimiento donde se desempeña el académico (en apoyo a la docencia, a la investigación o la difusión de la ciencia o arte), publicado por una editorial y con registro ISBN.', '(se acredita un solo capítulo por libro): El Colegio Departamental evalúa, a solicitud de la academia respectiva, la congruencia disciplinar del libro en el área de conocimiento del docente para turnarlo al Colegio de Facultad Interdisciplinaria para la revisión y acreditación de la actividad. Para ello, el Colegio de la Facultad Interdisciplinaria deberá revisar la portada, página legal que incluya ISBN y colofón en caso de libros impresos. En aquellos casos que en las evidencias presentadas no aparezca el nombre del traductor, deberá entregar, además, el documento escrito emitido por la editorial, donde conste su participación como traductor del libro.', 40, 1),
  (12, 'I.1.1.12', 'Elaboración de exámenes departamentales.', 'Exámenes estandarizados reconocidos de aplicación generalizada en todos los grupos de una asignatura, reconocidos por los Colegios Departamentales y elaborados de acuerdo a la metodología institucional.', 'El Colegio Departamental acredita la participación en la elaboración del examen departamental con base en acta de aprobación en los términos indicados en la definición. El jefe de departamento acredita la aplicación del examen departamental, con base en acta de aprobación en los términos indicados en la definición.', 40, 1),
  (13, 'I.1.1.13', 'Actualización de exámenes departamentales.', 'Trabajo de análisis técnico que consiste en la identificación con base en los criterios de calidad métrica, de los elementos de una prueba aplicada, que han perdido su capacidad discriminante, que ya no funcionan y sugerir nuevos reactivos que cumplen los mismos criterios de calidad para sustituirlos en la prueba.', 'El Colegio Departamental acredita la participación en la actualización del examen departamental, con base en acta de aprobación en los términos indicados en la definición. El jefe de departamento acredita la aplicación del examen departamental, con base en acta de aprobación en los términos indicados en la definición.', 20, 1),
  (14, 'I.1.1.14', 'Impartición de cursos o diplomados de actualización disciplinaria o didáctica.', 'Implementar el conjunto de acciones y experiencias de aprendizaje diseñadas de manera sistemática e intencional para desarrollar los conocimientos, habilidades y destrezas con la audiencia que se especifique en el proyecto formativo de acuerdo a la normatividad vigente. Puede ser impartido en modalidad presencial, en línea o mixto.', '1) El Colegio de Facultad Interdisciplinaria, la Secretaría General Académica, las Direcciones Administrativas o las Direcciones Administrativas de Campus, acreditan la impartición de diplomados, cursos o talleres mediante constancia oficial. 2) Cuando el curso o diplomado es organizado por instituciones externas, el solicitante captura en el sistema del programa y documenta en su expediente la actividad mediante constancia y acuerdo formal o documento firmado por autoridades de ambas instituciones, para que finalmente la actividad sea valorada por la Comisión Institucional de Evaluación.', 40, 1),
  (15, 'I.1.1.15', 'Implementación de espacios educativos en idioma inglés o distinto al español.', 'Implementación de un espacio educativo impartido en idioma inglés o distinto al español en el marco de un plan de estudio. No se incluyen los cursos de idiomas.', 'La actividad se acredita automáticamente a través de la información del espacio educativo impartido en idioma inglés o distinto al español, aprobado por el Colegio Departamental y registrado por el Jefe de Departamento en el Sistema Integral de Información Administrativa.', 40, 1),
  (16, 'I.1.1.16', 'Docencia colaborativa o clases tipo COIL - Aprendizaje colaborativo internacional en línea (Collaborative Online International Learning).', 'Profesores que diseñan e imparten junto con uno o más académicos de otras instituciones extranjeras, como parte de su clase, actividades que pongan en contacto a estudiantes y profesores para aprender, discutir y colaborar entre sí. Los profesores participan en el diseño de la experiencia y los alumnos en la ejecución de las actividades diseñadas. El enfoque es académico e intercultural.', 'El Colegio de Facultad Interdisciplinaria, el Colegio Departamental o la Dirección de Apoyo a Estudiantes, acredita la actividad con base en los informes presentados y en las evidencias de la realización de la colaboración del académico y su par, tales como el programa elaborado en conjunto y las evidencias que pueden ser: capturas de pantalla de sesiones, páginas en redes sociales y/o plataformas utilizadas.', 10, 1),
  (17, 'I.1.1.17', 'Clases espejo.', 'Impartición de algún tópico o tema en colaboración con otro académico, de una universidad extranjera, en línea. Las sesiones se organizan previamente por los titulares académicos para delimitar los temas que cada uno abordará y son complementarios para el espacio educativo del par socio. Los estudiantes de ambas instituciones asisten a la clase impartida por el profesor invitado. Las actividades de los estudiantes son independientes y pueden incluir debates o algún proyecto extra clase opcional.', 'El Colegio de Facultad Interdisciplinaria, el Colegio Departamental o la Dirección de Apoyo a Estudiantes acredita con base en convenio específico y constancia oficial.', 5, 1),
  (18, 'I.1.1.18', 'Diplomado de actualización didáctica o disciplinaria recibido.', 'Participación en un evento formativo de actualización y capacitación, cuyo objetivo es transmitir habilidades para atender situaciones de importancia profesional o social. Se organizan en módulos estructurados en un programa de estudios y su duración mínima es de 120 horas.', '1) El Colegio de la Facultad Interdisciplinaria, la Secretaría General Académica o las Direcciones Administrativas o Direcciones Administrativas de Campus acreditan la asistencia a diplomados de actualización didáctica o disciplinar mediante constancia oficial, de acuerdo con la normatividad vigente. 2) El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia, esto es cuando el diplomado es organizado por instituciones externas, especificando: nombre de evento formativo, lugar, fecha y número de horas de duración, para que la actividad sea valorada por la Comisión Institucional de Evaluación.', 60, 1),
  (19, 'I.1.1.19', 'Cursos y talleres recibidos de actualización disciplinaria.', 'Con base en la normatividad vigente por la Universidad de Sonora, se considera: Curso: participación en un evento formativo que promueve la experiencia de aprendizaje que proporciona elementos teóricos y metodológicos de un tema o problemática específica de la disciplina. Tiene objetivos claros y puede constituirse como una actividad modular de un Diplomado. El valor curricular es a partir de 20 horas. Taller: participación en un evento formativo que propicia una forma de trabajo en donde el participante construye su aprendizaje por medio de la realización de ejercicios que son definidos a partir de un programa de formación integrado por temas que responden a objetivos de aprendizaje concretos de la disciplina. El valor curricular es a partir de 10 horas.', '1) El Consejo de la Facultad Interdisciplinaria, la Secretaría General Académica o las Direcciones Administrativas o las Direcciones Administrativas de Campus, acreditan la asistencia a cursos o talleres de actualización disciplinar mediante constancia oficial, de acuerdo con los criterios para la formulación y aprobación de eventos formativos de actualización y capacitación ofrecidos por la Universidad de Sonora. 2) El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia, cuando el curso o taller es organizado por instituciones externas, especificando: nombre del evento formativo, lugar, fecha y número de horas de duración, para que la actividad sea valorada por la Comisión Institucional de Evaluación.', 20, 1),
  (20, 'I.1.1.20', 'Cursos y talleres recibidos de actualización didáctica.', 'Con base en la normatividad vigente, se considera: Curso: participación en un evento formativo que promueve la experiencia de aprendizaje que proporciona elementos teóricos y metodológicos de un tema o problemática específica de la didáctica de la disciplina y/o de la educación superior. Tiene objetivos claros y puede constituirse como una actividad modular de un Diplomado. El valor curricular es a partir de 20 horas. Taller: participación en un evento formativo que propicia una forma de trabajo en donde el participante construye su aprendizaje por medio de la realización de ejercicios que son definidos a partir de un programa de formación integrado por temas que responden a objetivos de aprendizaje concretos de la disciplina. El valor curricular es a partir de 10 horas.', '1) El Colegio de la Facultad Interdisciplinaria, la Secretaría General Académica o las Direcciones Administrativas o las Direcciones Administrativas de Campus, acreditan la asistencia a cursos o talleres de actualización de la didáctica de la disciplina y/o de la educación superior, mediante constancia oficial, de acuerdo con la normatividad vigente. 2) El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia, esto es, cuando el curso o taller es organizado por instituciones externas, especificando; nombre del evento formativo, lugar, fecha y número de horas de duración, para que la actividad sea valorada por la Comisión Institucional de Evaluación.', 20, 1),
  (21, 'I.1.1.21', 'Diplomados, cursos o talleres recibidos dentro del Programa Institucional de Desarrollo de Competencias docentes. (PIDCD).', 'Diplomado: Participación en un evento formativo de actualización y capacitación, cuyo objetivo es transmitir habilidades para atender situaciones de importancia profesional o social. Se organizan en módulos estructurados en un programa de estudios y su duración mínima es de 120 horas. Curso: Participación en un evento formativo, en el marco de las líneas temáticas que promueve el PIDCD y que propicia la Experiencia de aprendizaje que proporciona elementos teóricos y metodológicos de un tema o problemática específica de la didáctica de la práctica docente. Tiene objetivos claros y puede constituirse como una actividad modular de un Diplomado. El valor curricular es a partir de 20 horas. Taller: Participación en un evento formativo, en el marco de las líneas temáticas que promueve el PIDCD y que propicia una Forma de trabajo en donde el participante construye su aprendizaje por medio de la realización de ejercicios que son definidos a partir de un programa de formación integrado por temas que responden a objetivos de aprendizaje concretos de la didáctica de la práctica docente. El valor curricular es a partir de 10 horas.', 'La Secretaría General Académica acredita a través de la Dirección de Apoyo a Programas Educativos, tomando como evidencia constancia oficial de participación en el evento formativo, expedida por dichas instancias. Si el evento se lleva a cabo en conjunto con otra instancia universitaria o con alguna organización externa, la Secretaría General Académica acredita considerando la constancia oficial de participación.', 60, 1),
  (22, 'I.1.1.22', 'Espacios para la enseñanza en línea.', 'Ambiente digital diseñado y elaborado para la enseñanza en línea tanto de manera sincrónica (interacción alumno-docente en tiempo real) como asincrónica (interacción alumno-docente no en tiempo real), estos se deberán apegar al contenido del espacio educativo aprobado en el plan de estudios respectivo. Para cursos de educación continua (extracurriculares), la instancia administrativa responsable de impartirlo deberá contar con la aprobación de la Secretaría General Académica.', 'La Dirección de Apoyo a Programas Educativos o la instancia responsable en su momento, será quien acredite que el espacio diseñado cumple con los criterios institucionales para un espacio para la enseñanza en línea de manera sincrónica o asincrónica, previa aprobación del contenido por la academia y el Colegio de Facultad Disciplinaria respectivo. Este será acreditado solamente una vez. En el caso del rediseño del espacio para la enseñanza en línea, se considerará una vez que el diseño original se haya impartido al menos dos años de su aprobación, y que además se trate de al menos un 40% de actualización en el contenido de los materiales del espacio.', 50, 1),
  (23, 'I.1.1.23', 'Impartición de un curso en un espacio diseñado para la enseñanza en línea de manera sincrónica o asincrónica.', 'Impartición de un curso en un espacio digital diseñado y elaborado para la enseñanza en línea de manera sincrónica o asincrónica, mismo que deberá apegarse al contenido del espacio educativo aprobado en el plan de estudios respectivo. Para el caso de cursos de educación continua, deberán cumplir lo establecido en la normatividad vigente.', 'El Colegio Departamental acredita mediante constancia que certifique, previa entrega del producto y a solicitud de la academia respectiva, la pertinencia del ambiente digital construido y utilizado en el transcurso del programa educativo que atiende. Para el caso de cursos de educación continua (extracurriculares), la instancia administrativa responsable de impartirlo deberá contar con la aprobación de la Secretaría General Académica.', 20, 1),
  (24, 'I.1.1.24', 'Premios', 'Premio recibido a través de la participación en una convocatoria abierta, de institución u organismo de reconocido prestigio, por su trabajo académico en la disciplina del docente.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante la convocatoria y diploma o dictamen del premio recibido, para que sea valorado por la Comisión Institucional de Evaluación.', 80, 1),
  (25, 'I.1.1.25', 'Distinciones recibidas por trayectoria y productividad.', 'Reconocimiento recibido por el personal académico en virtud de su destacada trayectoria y/o productividad académica en el ámbito de la educación superior.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante el dictamen o constancia de la comisión, institución, organismo o asociación de reconocido prestigio de la disciplina del docente y copia de la convocatoria, para que sea valorado por la Comisión Institucional de Evaluación. Cuando un profesor participe como adjunto o visitante en alguna institución de educación superior, deberá presentar invitación o convocatoria, así como informe de actividades realizadas.', 60, 1),
  (26, 'I.1.1.26', 'Producción y participación en programas de radio, televisión u otros medios electrónicos de difusión.', 'Participación como miembro del equipo de producción (conductor, guionista) de programas de radio, televisión u otros medios electrónicos de difusión de la Universidad de Sonora o como docente invitado en dichos programas. Participación en radio, televisión u otros medios electrónicos de difusión fuera de ésta, deberá estar relacionada con productos de investigación de la disciplina del docente.', 'La Secretaría General Académica, las Coordinaciones Generales de las Facultades Interdisciplinarias, las Direcciones Administrativas o los Jefes de Departamento acreditan la actividad con base en constancia de nombramiento en el equipo de producción del programa, expedida por el titular de la radio o televisión de la Universidad de Sonora e informe de los programas realizados en el periodo a evaluar. Para el caso de invitados, constancia de participación expedida por el titular del programa de radio o televisión.', 30, 1),
  (27, 'I.1.1.27', 'Producción de materiales para actividades de difusión.', 'Elaboración de materiales (videos, carteles y similares) para su utilización en apoyo a las actividades académicas de la función de difusión.', 'El Colegio Facultad acredita mediante constancia que certifique, previa entrega del producto, a solicitud de la academia respectiva, la pertinencia del material y su uso generalizado en las actividades académicas de difusión realizadas en el programa educativo o en el Departamento correspondiente.', 30, 1),
  (28, 'I.1.1.28', 'Director de grupos artísticos universitarios.', 'Participación en la dirección de uno de los grupos artísticos de la Universidad de Sonora.', 'La Dirección de Apoyo a la Vinculación y Difusión, o el Colegio Departamental de Bellas Artes o las Direcciones Administrativas de Campus acreditan mediante constancia de nombramiento e informe de actividades.', 40, 1),
  (29, 'I.1.1.29', 'Dominio de lenguas extranjeras.', 'Dominio de un idioma diferente al del país de origen del profesor solicitante.', '3) Para Hispanohablantes: El solicitante documenta, en una sola ocasión, para que la comisión institucional de evaluación acredite la actividad, alguna de las siguientes opciones: 3.1) Obtener 500 puntos del TOEFEL o su equivalencia en otra lengua, o 3.2) Haber obtenido un grado universitario en lengua diferente al español. 3.3) Constancia vigente del nivel C1 MCER (Marco Común Europeo de Referencia para las Lenguas) en inglés. 3.4) Programa Institucional de Formación Docente para la Habilitación en la Enseñanza en Idioma Inglés. El Departamento de Lenguas Extranjeras acredita el dominio del idioma español, para el caso de profesores provenientes de países donde se hable otro idioma diferente del español.', 20, 1),
  (30, 'I.1.1.30', 'Evaluación al desempeño docente: Alumnos (Anexo 2).', 'Promedio de las evaluaciones de los alumnos obtenidas en los dos periodos escolares que comprende la convocatoria.', 'A través de la información obtenida por medio del Sistema Integral de Información Administrativa (SIIA).', 50, 1),
  (31, 'I.1.1.31', 'Evaluación al desempeño docente: Academia (Anexo 3).', 'Promedio de las evaluaciones de la academia respectiva obtenidas en los dos periodos escolares que comprende la convocatoria.', 'A través de la información obtenida por medio del SIIA. Cuando el docente que participa cuenta con nombramiento de Presidente de Academia, la evaluación de su desempeño en este rubro, será emitida por el Jefe de Departamento.', 30, 1),
  (32, 'I.1.1.32', 'Evaluación al desempeño docente: Jefe de Departamento (Anexo 4).', 'Promedio de las evaluaciones del Jefe de Departamento obtenidas en los dos periodos escolares que comprende la convocatoria.', 'A través de la información obtenida por medio del SIIA. Cuando el docente que participa cuenta con nombramiento de jefe de departamento, la evaluación de su desempeño en este rubro, será emitida por la persona titular de la Coordinación General de la Facultad Interdisciplinaria correspondiente.', 30, 1),
  (33, 'I.2.1', 'Distinción Sistema Nacional de Investigadoras e Investigadores (SNII)', 'Distinción SNI, es el reconocimiento público que otorga el Gobierno Federal a través del SECIHTI a humanistas, científicos, tecnólogos e innovadores que realicen actividades de investigación humanística o científica, desarrollo tecnológico o innovación en México, cualquiera que sea su nacionalidad, y aquellos de nacionalidad mexicana que realicen actividades de investigación humanística o científica, desarrollo tecnológico o innovación en el extranjero (DOF: última reforma publicada 20/04/2021).', 'La Dirección de Apoyo a Docentes, Investigación y Posgrado, o la Dirección que la sustituya, acredita mediante dictamen entregado por el solicitante, el cual deberá estar vigente en el período evaluado.', 200, 2),
  (34, 'I.2.2', 'Distinción Sistema Nacional de Creadores de Arte (SNCA)', 'Distinción SNCA es el reconocimiento público que otorga el Gobierno Federal para estimular a los creadores de talento y excelencia, con acciones de fomento a la creación individual para contribuir al incremento del patrimonio cultural de México (DOF: 28/11/2017).', 'La Dirección de Apoyo a Docentes, Investigación y Posgrado, o la Dirección que la sustituya, acredita mediante dictamen entregado por el solicitante, el cual deberá estar vigente en el período evaluado.', 150, 2),
  (35, 'I.2.3', 'Distinciones.', 'Reconocimiento recibido por el personal académico en virtud de su destacada labor de investigación o bien, por la creación de obra artística (autor de obra original).', 'El solicitante captura en el sistema del Programa de Estímulo al Desempeño del Personal Docente y documenta en su expediente la actividad mediante constancia oficial, para que sea valorado por la Comisión Institucional de Evaluación.', 80, 2),
  (36, 'I.2.4.1', 'Publicación de artículos en revistas de catálogo.', 'Artículo publicado en revista incluida en catálogos de información académica reconocida en los catálogos aprobados por el Colegio Académico o por el Colegio Universitario con base en el Estatuto de Personal Académico.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante la sección del artículo donde se especifique fecha de publicación, datos del editor, volumen y páginas, para que sea valorado por la Comisión Institucional de Evaluación.', 150, 2),
  (37, 'I.2.4.2', 'Publicaciones de artículos en revistas con arbitraje, no incluidas en catálogos aprobados por el Colegio Académico o por el Colegio Universitario', 'Artículo publicado en revista con arbitraje, que no figure en catálogos aprobado por el Colegio Académico o por el Colegio Universitario, pero reconocida por el Consejo Divisional o por el Colegio de Facultad interdisciplinaria correspondiente.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante la sección del artículo donde se especifique fecha de publicación, datos del editor, volumen y páginas, para que sea valorado por la Comisión Institucional de Evaluación.', 50, 2),
  (38, 'I.2.4.3', 'Participación como árbitro en publicaciones.', 'Participación como árbitro en el proceso de revisión en el período a evaluar en publicaciones incluidas en los catálogos aprobados por el Colegio Académico o por el Colegio Universitario con base en el Estatuto de Personal Académico.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante evidencia de participación de la evaluación, para que sea valorado por la Comisión Institucional de Evaluación.', 30, 2),
  (39, 'I.2.4.4', 'Participación como árbitro en ponencias.', 'Participación como árbitro en la aceptación de ponencias en eventos académicos.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante evidencia de participación como árbitro, para que sea valorado por la Comisión Institucional de Evaluación.', 20, 2),
  (40, 'I.2.4.5', 'Citas tipo A en el periodo a evaluar a publicaciones en libros o revistas de catálogo donde el docente sea referido como autor.', 'Publicación de libros o artículos donde el académico sea referido como autor.', 'La Subdirección de Servicios de Apoyo Académico o la instancia correspondiente, acredita las citas en libros o revistas de catálogo a través del Sistema Institucional Bibliotecario. El solicitante captura la información de citas en libros o revistas en el sistema del PEDPD (No incluye auto citas), lo cual será acreditado a través del Sistema Institucional Bibliotecario.', 100, 2),
  (41, 'I.2.5.1', 'Conferencias por invitación.', 'Exposición de un tema de interés académico a invitación expresa de los organizadores del evento académico.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante oficio de invitación y constancia oficial de presentación, expedidas por los organizadores y programa del evento, para que sea valorado por la Comisión Institucional de Evaluación.', 30, 2),
  (42, 'I.2.5.2', 'Participación con ponencia o cartel en congresos o eventos académicos de la especialidad del docente.', 'Trabajo académico presentado en forma oral o escrita en evento organizado por instituciones u organismos de reconocido prestigio en el área de conocimiento del docente.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia oficial de presentación, para que sea valorado por la Comisión Institucional de Evaluación.', 50, 2),
  (43, 'I.2.6.1', 'Responsable de proyectos de investigación (Solo un responsable por proyecto).', 'Personal académico responsable del registro, ejecución, seguimiento y control de un proyecto de investigación, así como de la presentación de los informes de avance o término de resultados, utilizando los recursos necesarios y atendiendo la normatividad vigente.', 'El Colegio Departamental acredita la actividad si el proyecto es disciplinar, si es interdisciplinar, acredita el Colegio de Facultad Interdisciplinaria correspondiente, con base en la captura del solicitante en el Sistema de Registro y Seguimiento de Proyectos de Investigación, de lo siguiente: 1) Con financiamiento externo 1.1) Constancia de aprobación del proyecto por el organismo financiador o bien, copia del convenio firmado entre la Universidad de Sonora y su contraparte. 1.2) Registro del proyecto. 1.3) Informe anual recibido por el organismo financiador o informe anual avalado por la Institución u organismo con el que se firmó el convenio. 1.4) Productos originados durante la realización del proyecto: artículos, ponencias o tesis. 2) Con financiamiento interno: 2.1) Registro del proyecto. 2.2) Informe de actividades, el cual debe ser aprobado por el Consejo Divisional o, debe ser aprobado por el Colegio Departamental si el proyecto es disciplinar; por el Colegio de Facultad Interdisciplinaria correspondiente si el proyecto es interdisciplinar correspondiente. 2.3) Productos originados durante la realización del proyecto: artículos, ponencias o tesis.', 150, 2),
  (44, 'I.2.6.2', 'Colaborador de proyectos de investigación.', 'Persona física designada por la/el responsable técnico del proyecto de investigación como participante del grupo de trabajo, teniendo en colaboración responsabilidad en el desarrollo de las actividades, metas y resultados comprometidos en un proyecto de investigación.', 'El Colegio Departamental o el Colegio de Facultad Interdisciplinaria acredita la actividad con base en la captura del responsable en el Sistema de Registro y Seguimiento de Proyectos de Investigación, de lo siguiente: 3) Con financiamiento externo. 3.1) Constancia de aprobación del proyecto por el organismo financiador o bien, copia del convenio firmado entre la Universidad de Sonora y su contraparte. 3.2) Registro del proyecto. 3.3) Informe anual recibido por el organismo financiador o informe anual avalado por la Institución u organismo con el que se firmó el convenio. 3.4) Productos originados durante la realización del proyecto: artículos, ponencias o tesis. 4) Con financiamiento interno: 4.1) Registro del proyecto. 4.2) Informe de actividades, el cual debe ser aprobado por el Colegio de Facultad Interdisciplinaria o por el Colegio Departamental si el proyecto es disciplinar; por el Colegio de Facultad Interdisciplinaria correspondiente si el proyecto es interdisciplinar. 4.3) Productos originados durante la realización del proyecto: artículos, ponencias o tesis.', 80, 2),
  (45, 'I.2.6.3', 'Proyecto de colaboración o prestación de servicios con el sector privado, público o social.', 'Desarrollo de actividades de vinculación en el marco de convenios institucionales o acuerdos formales entre unidades académicas y/o direcciones universitarias con instituciones, empresas u organismos de los sectores social o productivo.', 'El Colegio de la Facultad Interdisciplinaria correspondiente acredita con base en la presentación del convenio firmado entre la Universidad de Sonora y su contraparte o el acuerdo respectivo e informe anual avalado por el Colegio de Facultad Interdisciplinaria o la Secretaría General Académica (convenios o acuerdos establecidos por Direcciones Universitarias).', 60, 2),
  (46, 'I.2.7.1', 'Obtención de patentes para la Universidad de Sonora.', 'Realización de invenciones e innovaciones a través de protección mediante patentes, modelos de utilidad, diseños industriales o secretos industriales.', 'Patente: La Dirección de Apoyo a la Vinculación y Difusión o la instancia correspondiente, acredita considerando Título o certificado de la patente, que incluya el número expedido por el Instituto Mexicano de la Propiedad Industrial (IMPI) y validado por su código QR o su equivalente en otros países. Solicitud de Patente: La Dirección de Apoyo a la Vinculación o Difusión o la instancia correspondiente acredita considerando comprobante de solicitud de patente expedido por el IMPI o su equivalente en otros países.', 100, 2),
  (47, 'I.2.7.2', 'Elaboración de software con aplicación en área del desempeño del docente.', 'Diseño y producción de software para apoyo a las labores docentes, de investigación o extensión del personal académico.', 'El Colegio Departamental acredita mediante constancia que valide la presentación de listado de programa y manual de uso.', 60, 2),
  (48, 'I.2.7.3', 'Miembro del cuerpo académico registrado ante la Secretaría de Educación Pública (SEP).', 'Participación activa como miembro de un cuerpo académico.', 'La Dirección de Apoyo a la Docencia, Investigación y Posgrado o la instancia correspondiente, acredita la actividad con base en el Registro del Cuerpo Académico en PRODEP y captura del plan de trabajo e informe de actividades en el Sistema. El informe deberá incluir al menos tres actividades colegiadas desarrolladas por al menos dos miembros del Cuerpo Académico. El registro deberá estar vigente en el período evaluado.', 40, 2),
  (49, 'I.2.8', 'Gestión de proyectos para la creación de obra artística original (exclusivo para el personal de la Licenciatura en Artes).', 'Elaboración y gestión de proyectos de creación artística para participar en fondos concursables públicos y privados.', 'El Colegio Departamental acredita la actividad con base en lo siguiente: 1) Con financiamiento externo: 1.1) Convocatoria publicada y constancia de aceptación del proyecto por el organismo financiador o bien, copia del convenio firmado entre la Universidad de Sonora y su contraparte e, 1.2) Informe anual recibido por el organismo financiador o informe anual avalado por la Institución u organismo con el que se firmó el convenio. 1.3) Además, para el caso de informe final, el registro de la obra artística en la instancia competente. 2) Con financiamiento interno. 2.1) Constancia de registro del proyecto por el Colegio Departamental. 2.2) Informe anual o final aprobado por el Colegio Departamental correspondiente.', 80, 2),
  (50, 'I.2.9', 'Presentación de obras escénicas que cumplan temporada (exclusivo para el personal de la licenciatura en artes).', 'Presentación de obra artística musical, de teatro o danza que cumpla temporada con un número mínimo de 10 funciones.', 'El Colegio Departamental a solicitud de la academia respectiva acredita con base en la constancia de presentación de la obra.', 60, 2),
  (51, 'I.2.10', 'Presentación de obras artísticas en festivales u otro tipo de eventos académicos (exclusivo para el personal de la licenciatura en artes).', 'Presentación de obra artística musical, de teatro o danza en festival artístico u otro tipo de eventos académicos.', 'El Colegio Departamental a solicitud de la academia respectiva acredita con base en la constancia de presentación de la obra.', 60, 2),
  (52, 'I.2.11', 'Exposición de artes visuales.', 'Exposición de obra individual o colectiva (exposición de obra individual o colectiva de pintura, fotografía, grabado, escultura. cine, serigrafía, diseño, videoarte, instalación e intervención), en el área de desempeño del docente.', 'El Colegio Departamental a solicitud de la academia respectiva acredita con base en la constancia de presentación de la obra.', 50, 2),
  (53, 'I.3.1.1', 'Responsable de tutorías.', 'Docente acreditado como tutor que apoya las funciones de la Coordinación del Programa Docente en lo relativo al Programa de Tutorías y las tareas vinculadas a la mejora de las trayectorias escolares de los estudiantes en riesgo académico inscritos en el programa.', 'La Dirección de Apoyo a Estudiantes o la instancia correspondiente, acredita con base en el registro en el Sistema Tutorial de Acompañamiento Escolar del nombramiento oficial e informe semestral.', 120, 3),
  (54, 'I.3.1.2', 'Tutor académico de estudiante de licenciatura.', 'Docente que cumple con los requisitos y condiciones establecidos por la Comisión de Trayectorias Escolares para ejercer funciones de tutoría y está habilitado por la Coordinación del Programa Docente para ofrecer acompañamiento personalizado a un número de estudiantes en riesgo académico, considerando para su asignación, el resultado del seguimiento de las trayectorias escolares.', 'La Dirección de Apoyo a Estudiantes o la instancia correspondiente, acredita con base en la habilitación del docente y captura del informe semestral en el Sistema Tutorial de Acompañamiento Escolar.', 120, 3),
  (55, 'I.3.1.3', 'Responsable de prácticas profesionales de programa educativo', 'Profesor (a) que tiene como función asesorar, informar, coordinar y acreditar el proceso de las prácticas profesionales dentro de un programa educativo de los ofrecidos en el departamento de adscripción.', 'El Colegio Departamental acredita considerando el nombramiento y el informe presentado.', 120, 3),
  (56, 'I.3.1.4', 'Tutor de prácticas profesionales.', 'Docente asignado como tutor de prácticas profesionales de acuerdo a la normativa vigente.', 'El Coordinador de Prácticas Profesionales de la Facultad Interdisciplinaria correspondiente, acredita la actividad con base en el registro en el Sistema Integral de Información Administrativa, de la asignación del docente como tutor de prácticas profesionales y de la acreditación del total de créditos de las prácticas profesionales del estudiante.', 120, 3),
  (57, 'I.3.1.5', 'Tutor de servicio social.', 'Docente asignado como tutor de servicio social de acuerdo a la normativa vigente.', 'La Dirección de Apoyo a Estudiantes o el Coordinador del Servicio Social de la Facultad Interdisciplinaria, para el caso del Campus Hermosillo y el Área correspondiente, acredita la actividad con base en el registro de la asignación del docente como tutor de servicio social y registro de constancia de liberación, en el sistema de servicio social universitario.', 120, 3),
  (58, 'I.3.2', 'Tutor académico de estudiantes de posgrado.', 'Tutor académico de alumnos inscritos en un programa de posgrado, en términos de lo establecido en la normativa vigente.', 'Posgrados de la Universidad de Sonora (interno): El jefe del Departamento correspondiente acredita la actividad con base a la constancia del nombramiento e informe de actividades avalado por el coordinador de posgrado. Posgrados de otras Universidades (externos): El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad presentando nombramiento e informe de actividades avalado por el coordinador de programa y constancia de inscripción expedida por la autoridad competente, para que sea valorado por la Comisión Institucional de Evaluación.', 30, 3),
  (59, 'I.3.3', 'Premios otorgados a estudiantes por labor realizada bajo supervisión de docentes.', 'Dirección y asesoría de actividades académicas realizadas por alumnos, las cuales incidieron en forma directa y evidente a la obtención de un premio.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante: 1) Convocatoria respectiva y constancia oficial del premio otorgado al estudiante; además, constancia de la dirección del estudiante en las actividades realizadas, expedida por el Coordinador de Programa respectivo. 2) En el caso de premios a estudiantes de bachillerato, la constancia de la dirección del estudiante debe ser expedida por el director del plantel correspondiente. En ambos casos la documentación será valorada por la Comisión Institucional de Evaluación.', 40, 3),
  (60, 'I.3.4', 'Formación de estudiantes en proyectos de investigación.', 'Actividades de formación de estudiantes dentro de un proyecto de investigación o estancias de investigación.', 'El Colegio Departamental acredita la actividad o el Colegio de Facultad Interdisciplinaria, si participa en proyectos interdisciplinares con base en el informe de la investigación avalado por este órgano colegiado. Para estancias de investigación, presentar constancia de la instancia correspondiente.', 30, 3),
  (61, 'I.3.5.1', 'Dirección de tesis', 'Dirección de un trabajo de investigación cuyo objetivo sea la obtención del grado académico correspondiente.', '1) La Dirección de Servicios Escolares, o la instancia correspondiente, acredita la actividad a través del registro en el Sistema Integral de Información Administrativa del acta de examen profesional o de grado, atendiendo a lo establecido en el artículo 28 del Reglamento de PEDPD. 2) Cuando con una misma opción de titulación se titulan 2 o más estudiantes, sólo cuenta como una actividad, es decir, la acreditación es por actividad y no por el número de estudiantes titulados en dicha actividad. 3) El Jefe de Departamento acredita la actividad en el caso de que el director del trabajo de titulación no sea el presidente del jurado. 4) El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad de tesis de otras instituciones de educación superior mediante la constancia de dirección y acta de examen, para que sea valorado por la Comisión Institucional de Evaluación. 5) En caso de que el solicitante tenga cubierto el puntaje máximo en esta actividad, podrá acreditarse como Miembro de Jurado.', 120, 3),
  (62, 'I.3.5.2', 'Asesoría de trabajos académicos', 'Asesoría de trabajos académicos cuyo objetivo sea la obtención del grado académico correspondiente.', '1) El Jefe de Departamento acredita la asesoría de trabajo de titulación, con base en la constancia y copia del acta de examen profesional o de grado. 2) El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad de asesoría de tesis de otras instituciones de educación superior, presentando la constancia de asesoría y acta de examen, para que sea valorado por la Comisión Institucional de Evaluación.', 60, 3),
  (63, 'I.3.5.3', 'Miembro del jurado de examen profesional o de grado.', 'Participación en el jurado de un examen profesional o de grado.', '1) La Dirección de Servicios Escolares o la instancia correspondiente, acredita la actividad a través del registro en el SIIA del acta de examen profesional o de grado. 2) El Jefe de Departamento acredita la actividad en el caso de jurado suplentes, con base en el nombramiento y acta de examen.', 40, 3),
  (64, 'I.3.6.1', 'Asesoría en proyectos de alumnos extranjeros.', 'Profesores que imparten asesorías en el ámbito académico, de su experiencia, a estudiantes internacionales, en programas de colaboración formales avalados por convenios internacionales.', 'El Colegio Departamental acredita la actividad con el acta correspondiente en la que se aprueba el informe y constancia emitida por la institución de adscripción del estudiante que indique las horas y actividad.', 10, 3),
  (65, 'I.3.6.2', 'Asesor de grupos de estudiantes en programas de extensión y vinculación.', 'Académico que orienta y brinda asesoría a un grupo de estudiantes que participan en programas de extensión y vinculación.', '1) El Colegio Departamental acredita la actividad en el caso de programas organizados por Facultades o Departamentos, con base en actas del Colegio de Facultad Interdisciplinaria en las que conste tanto el registro como la aprobación del informe de actividades. En el caso de programas organizados por Facultades Interdisciplinarias, se debe acreditar la actividad con base en actas de la Facultad Interdisciplinaria correspondiente 2) En el caso de programas organizados por otras dependencias, la actividad la acredita quien funja como titular de la Dirección o la instancia correspondiente, con base en la constancia de registro e informe de actividades avalado por la misma.', 25, 3),
  (66, 'I.3.6.3', 'Impartición de eventos formativos de actualización y capacitación extracurricular dirigidos a estudiantes.', 'Realización de actividades de asesoría extracurricular de apoyo a los estudiantes conforme a la normativa vigente.', 'El Colegio de Facultad Interdisciplinaria acredita la actividad con base al acta en la que conste tanto el registro como la aprobación del informe de actividades. El Colegio Departamental acredita la actividad cuando ésta es disciplinar.', 50, 3),
  (67, 'I.3.6.4', 'Preparación de estudiantes para competencias académicas y/o artísticas o exámenes interescolares e interinstitucionales.', 'Asesoría académica a estudiantes de educación superior o bachillerato en su preparación para la participación en competencias académicas, tales como las Olimpiadas de Química, Olimpiadas Física, Concursos de Escuelas Incorporadas, entre otras.', 'El Colegio Departamental acredita la actividad con base en el acta en la que conste el nombramiento tanto del coordinador del cuerpo de asesores, como de cada uno de ellos e Informe de actividades aprobado por este órgano colegiado.', 25, 3),
  (68, 'I.3.6.5', 'Preparación de alumnos para la presentación del Examen General para el Egreso de la Licenciatura (EGEL).', 'Participación formal en la preparación de alumnos que presenten el EGEL aplicado por el Centro Nacional de Evaluación para la Educación Superior (CENEVAL).', 'El Colegio Departamental acredita la actividad con base en el acta en la que conste el nombramiento tanto del coordinador del cuerpo de asesores, como de cada uno de ellos e Informe de actividades aprobado por este órgano colegiado.', 25, 3),
  (69, 'I.3.6.6', 'Asesor de estudiantes para presentación de ponencias en eventos académicos.', 'Asesor de estudiantes para la presentación de trabajos orales o escritos en eventos académicos, tales como las muestras estudiantiles y los eventos nacionales e internacionales que cuentan con sección de ponencias para estudiantes.', 'El Jefe de Departamento acredita la actividad con base en el nombramiento como asesor y constancia oficial de presentación de la ponencia. Se acreditará por ponencia independientemente del número de alumnos y número de eventos.', 50, 3),
  (70, 'I.4.1.1', 'Integrante de Comisiones Dictaminadoras.', 'Responsables de evaluar y calificar las solicitudes de asignación y/o promoción de nivel del personal académico.', 'El Colegio Departamental acredita la actividad con base en el nombramiento y la constancia de presentación del informe anual en los términos señalados en los artículos 45 y 59 respectivamente, del Estatuto de Personal Académico.', 60, 4),
  (71, 'I.4.1.2', 'Presidente o secretario de Academia', 'Persona que preside o dirige una academia. Es representante y portavoz de la misma, contando con el apoyo del docente nombrado como secretario de academia.', 'El Jefe de Departamento acredita la actividad con base en el nombramiento e informe de actividades presentado por el docente.', 60, 4),
  (72, 'I.4.1.3', 'Integrante de órgano colegiado interno o comisiones.', 'Integrante de Colegio Departamental, Colegio de Facultad Interdisciplinaria o de Colegio Universitario (mínimo 4 meses de vigencia del nombramiento durante el periodo a evaluar).', 'El presidente del cuerpo colegiado correspondiente acredita la actividad: 1) En el caso de integrante de órgano colegiado, con base en el nombramiento oficial y constancia en la que se indique el cumplimiento de al menos el 80% de asistencia a las sesiones del órgano colegiado y/o las reuniones de las comisiones del mismo, según el caso. 2) En el caso de comisiones, con base en constancia de la secretaría técnica del cuerpo colegiado de entrega de informe anual.', 60, 4),
  (73, 'I.4.1.4', 'Integrante de comisiones internas y externas.', 'Integrantes de comisiones nombradas por órganos colegiados, órganos personales o direcciones universitarias o bien, por la autoridad competente en el caso de comisiones externas.', '1) En caso de comisiones internas, el órgano colegiado, personal o instancia correspondiente acredita la actividad con base en el informe de actividades avalado por éste y constancia en la que se especifique el cumplimiento de al menos el 80% de asistencia a las reuniones de las comisiones del mismo. 2) En caso de comisiones externa, el solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante nombramiento y constancia de participación en las actividades.', 40, 4),
  (74, 'I.4.1.5', 'Miembro de Comisión interna para preparación de la evaluación con fines de acreditación de programas.', 'Integrante de comisiones nombradas por Jefes de Departamento o por los titulares de las Coordinaciones Generales de Facultades Interdisciplinarias, las cuales tienen como objetivo la evaluación con fines de acreditación o el seguimiento de la acreditación de los Programas Educativos de Licenciatura o el reconocimiento de calidad de Posgrado.', '1) El Jefe de Departamento, o el Coordinador General de Facultad Interdisciplinaria, según sea el caso, acredita la actividad con base en las constancias de participación en las actividades de preparación de la evaluación. 2) La Dirección de Apoyo a Programas Educativos, o la instancia correspondiente avala la conclusión de la autoevaluación del programa. La Dirección de Apoyo a Docentes, Investigación y Posgrado o la instancia correspondiente acredita el reconocimiento de Posgrados de calidad.', 60, 4),
  (75, 'I.4.2.1', 'Organización de congresos académicos.', 'Organización de congresos académicos cuyo componente principal es la presentación, mediante convocatoria, de ponencias arbitradas.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia expedida por el responsable de la dependencia organizadora del evento, indicando nombre lugar y fecha de realización, para que sea valorado por la Comisión Institucional de Evaluación. Además, en el caso de congresos nacionales o internacionales se deberán presentar evidencias que justifiquen el nivel de acreditación solicitado.', 40, 4),
  (76, 'I.4.2.2', 'Organización de eventos académicos.', 'Organización de eventos académicos diferentes a la categoría de congreso, con base en la normatividad vigente, organizados por la Universidad de Sonora, así como los eventos aprobados el Colegio Departamental o el Colegio de Facultad Interdisciplinaria correspondiente.', '1) Para eventos internos, el Colegio Departamental, el Colegio de la Facultad Interdisciplinaria, la Secretaría General Académica o Direcciones Administrativas, acreditan la actividad, con base en la constancia expedida por el responsable de la dependencia organizadora del evento, indicando nombre lugar y fecha de realización del evento e informe detallado sobre el cumplimiento de los objetivos avalado por la dependencia correspondiente. 2) Para eventos externos, el solicitante captura en el sistema del PEDPD y documenta en su expediente presentando constancia expedida por el responsable de la dependencia organizadora del evento, indicando nombre lugar y fecha de realización del evento e informe detallado sobre el cumplimiento de los objetivos avalado, para que sea valorado por la Comisión Institucional de Evaluación. Además, en el caso de eventos nacionales o internacionales se deberá presentar evidencias que justifiquen el nivel de acreditación solicitado.', 30, 4),
  (77, 'I.4.3.1', 'Integrante de comité editorial de publicación.', 'Participación como miembro del comité editorial de publicaciones en el área del conocimiento del docente.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad, presentando ejemplares editados en el periodo correspondiente, en los que aparezcan los nombres de los miembros del comité editorial, para que sea valorado por la Comisión Institucional de Evaluación.', 20, 4),
  (78, 'I.4.3.2', 'Evaluador de proyectos de investigación.', 'Participación como evaluador de proyectos de investigación sometidos a la aprobación de instituciones reconocidas.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia oficial de participación en el periodo a evaluar, para que sea valorado por la Comisión Institucional de Evaluación.', 40, 4),
  (79, 'I.4.3.3', 'Miembro o evaluador de organismos acreditadores de programas y/o profesionistas.', 'Participación como miembro de comité o evaluador de organismos dedicados a la evaluación, acreditación o certificación de programas académicos, procesos o profesionistas.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente la actividad mediante constancia oficial de participación en el periodo a evaluar, para que sea valorado por la Comisión Institucional de Evaluación.', 50, 4),
  (80, 'I.4.3.4', 'Miembro de jurado en exámenes de ingreso del personal académico.', 'Participación como miembro de jurado para el ingreso del personal académico, de acuerdo a lo establecido en el Estatuto de Personal Académico.', 'El Colegio Departamental acredita la actividad con base en la constancia de nombramiento y resolución emitida por el jurado.', 40, 4),
  (81, 'I.4.3.5', 'Miembro del jurado para el otorgamiento de distinciones o premios de reconocimiento académico o profesional', 'Participación como miembro del comité responsable del otorgamiento de premios o distinciones a instituciones, académicos, profesionistas o estudiantes.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente mediante la presentación de constancia oficial de participación en la actividad en el periodo a evaluar, para que sea valorado por la Comisión Institucional de Evaluación.', 40, 4),
  (82, 'O.1.1', 'Otras evidencias', 'Actividad académica, de investigación, difusión o vinculación relevante para el área de desempeño del personal académico que no se encuentra contemplada en las categorías anteriores.', 'El solicitante captura en el sistema del PEDPD y documenta en su expediente mediante la presentación de constancia oficial de participación en la actividad en el periodo a evaluar, para que sea valorado por las instituciones relevantes.', 0, 5);
